"use client";

import { IconInfo } from "@/components/icons";

type BarItem = {
  label: string;
  current: number;
  previous: number;
};

function ChartCard({
  title,
  items,
  max,
}: {
  title: string;
  items: BarItem[];
  max: number;
}) {
  return (
    <div className="rounded-[10px] border border-icr-border bg-icr-surface p-4">
      <h3 className="mb-3.5 mt-0 text-sm font-semibold text-icr-navy">{title}</h3>
      {items.map((item) => (
        <div
          className="mb-3 grid grid-cols-[110px_1fr_28px] items-center gap-2"
          key={item.label}
        >
          <div className="text-xs leading-4 text-icr-navy">{item.label}</div>
          <div className="flex min-w-0 flex-col gap-1">
            <div className="relative h-2 overflow-hidden rounded-full">
              <span
                className="relative block h-full rounded-full bg-icr-bar"
                style={{ width: `${(item.current / max) * 100}%` }}
              />
            </div>
            <div className="relative h-2 overflow-hidden rounded-full">
              <span
                className="relative block h-full rounded-full bg-icr-bar-prev"
                style={{ width: `${(item.previous / max) * 100}%` }}
              />
            </div>
          </div>
          <div className="text-right text-xs font-semibold text-icr-navy">
            {item.current}
          </div>
        </div>
      ))}
      <div className="mt-1 ml-[110px] flex justify-between pr-7 text-[11px] text-icr-muted">
        <span>0</span>
        <span>{Math.round(max * 0.25)}</span>
        <span>{Math.round(max * 0.5)}</span>
        <span>{Math.round(max * 0.75)}</span>
        <span>{max}</span>
      </div>
      <div className="mt-3 flex justify-center gap-4 text-xs text-icr-muted">
        <span className="inline-flex items-center gap-1.5">
          <i className="inline-block h-2 w-2 rounded-full bg-icr-bar" /> Current month
        </span>
        <span className="inline-flex items-center gap-1.5">
          <i className="inline-block h-2 w-2 rounded-full bg-[#d1d5db]" /> Previous month
        </span>
      </div>
    </div>
  );
}

